function GenericGenObject:_init(io, parent, root)
  KaitaiStruct._init(self, io)
  self._parent = parent
  self._root = root or self
  self:_read()
end

function GenericGenObject:_read()
  if self.ofs < 0 then
    self.save_ofs = self._io:read_bytes(0)
  end
  self.obj = GenericGenObject.GenObj(self._io, self, self._root)
end

GenericGenObject.property.ofs = {}
function GenericGenObject.property.ofs:get()
  if self._m_ofs ~= nil then
    return self._m_ofs
  end

  self._m_ofs = self._io:pos()
  return self._m_ofs
end

GenericGenObject.property.data = {}
